198	/**
199	 * Extracts a human-readable text representation from a Message object.
200	 * Handles Text, Data (JSON), and File parts.
201	 */
202	export function extractMessageText(message: Message | undefined): string {
203	  if (!message || !message.parts || !Array.isArray(message.parts)) {
204	    return '';
205	  }
206	
207	  return extractPartsText(message.parts, '\n');
208	}
209	
210	/**
211	 * Extracts text from an array of parts, joining them with the specified separator.
212	 */
213	function extractPartsText(
214	  parts: Part[] | undefined,
215	  separator: string,
216	): string {
217	  if (!parts || parts.length === 0) {
218	    return '';
219	  }
220	  return parts
221	    .map((p) => extractPartText(p))
222	    .filter(Boolean)
223	    .join(separator);
224	}
225	
226	/**
227	 * Extracts text from a single Part.
228	 */
229	function extractPartText(part: Part): string {
230	  if (isTextPart(part)) {
231	    return part.text;
232	  }
233	
234	  if (isDataPart(part)) {
235	    return `Data: ${JSON.stringify(part.data)}`;
236	  }
237	
238	  if (isFilePart(part)) {
239	    const fileData = part.file;
240	    if (fileData.name) {
241	      return `File: ${fileData.name}`;
242	    }
243	    if ('uri' in fileData && fileData.uri) {
244	      return `File: ${fileData.uri}`;
245	    }
246	    return `File: [binary/unnamed]`;
247	  }
248	
249	  return '';
250	}
