50	  static getInstance(): A2AClientManager {
51	    if (!A2AClientManager.instance) {
52	      A2AClientManager.instance = new A2AClientManager();
53	    }
54	    return A2AClientManager.instance;
55	  }
56	
57	  /**
58	   * Resets the singleton instance. Only for testing purposes.
59	   * @internal
60	   */
61	  static resetInstanceForTesting() {
62	    // @ts-expect-error - Resetting singleton for testing
63	    A2AClientManager.instance = undefined;
64	  }
