66	  /**
67	   * Loads an agent by fetching its AgentCard and caches the client.
68	   * @param name The name to assign to the agent.
69	   * @param agentCardUrl The full URL to the agent's card.
70	   * @param authHandler Optional authentication handler to use for this agent.
71	   * @returns The loaded AgentCard.
72	   */
73	  async loadAgent(
74	    name: string,
75	    agentCardUrl: string,
76	    authHandler?: AuthenticationHandler,
77	  ): Promise<AgentCard> {
78	    if (this.clients.has(name) && this.agentCards.has(name)) {
79	      throw new Error(`Agent with name '${name}' is already loaded.`);
80	    }
81	
82	    let fetchImpl: typeof fetch = fetch;
83	    if (authHandler) {
84	      fetchImpl = createAuthenticatingFetchWithRetry(fetch, authHandler);
85	    }
86	
87	    const resolver = new DefaultAgentCardResolver({ fetchImpl });
88	
89	    const options = ClientFactoryOptions.createFrom(
90	      ClientFactoryOptions.default,
91	      {
92	        transports: [
93	          new RestTransportFactory({ fetchImpl }),
94	          new JsonRpcTransportFactory({ fetchImpl }),
95	        ],
96	        cardResolver: resolver,
97	      },
98	    );
99	
100	    const factory = new ClientFactory(options);
101	    const client = await factory.createFromUrl(agentCardUrl, '');
