131	  async *sendMessageStream(
132	    agentName: string,
133	    message: string,
134	    options?: { contextId?: string; taskId?: string; signal?: AbortSignal },
135	  ): AsyncIterable<SendMessageResult> {
136	    const client = this.clients.get(agentName);
137	    if (!client) {
138	      throw new Error(`Agent '${agentName}' not found.`);
139	    }
140	
141	    const messageParams: MessageSendParams = {
142	      message: {
143	        kind: 'message',
144	        role: 'user',
145	        messageId: uuidv4(),
146	        parts: [{ kind: 'text', text: message }],
147	        contextId: options?.contextId,
148	        taskId: options?.taskId,
